const { useState } = React;

function App() {
  const [size, setSize] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [addedToCart, setAddedToCart] = useState(false);
  const [page, setPage] = useState("product");
  const [errors, setErrors] = useState({});

  const description =
    "Experience ultimate comfort and performance with our Running Shoes, designed for every stride you take.";

  function validate() {
    const newErrors = {};
    if (!size) newErrors.size = "Please select a size.";
    if (!quantity || quantity < 1 || !Number.isInteger(Number(quantity))) {
      newErrors.quantity = "Please enter a valid quantity (1 or more).";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleAddToCart() {
    if (!validate()) return;
    setAddedToCart(true);
  }

  if (page === "checkout") {
    return (
      <main style={styles.checkout}>
        <h1>Checkout</h1>
        <p>You are buying:</p>
        <ul>
          <li><strong>Product:</strong> Running Shoes</li>
          <li><strong>Size:</strong> {size}</li>
          <li><strong>Quantity:</strong> {quantity}</li>
          <li><strong>Total Price:</strong> ${89 * quantity}</li>
        </ul>
        <button onClick={() => setPage("product")} style={styles.button}>
          Back to Product
        </button>
      </main>
    );
  }

  return (
    <main style={styles.container}>
      <section style={styles.imageSection}>
        <img
          src="/runtime/photos/product.jpg"
          alt="Running Shoes"
          style={styles.image}
        />
      </section>
      <section style={styles.detailsSection}>
        <h1 style={styles.title}>Running Shoes</h1>
        <p style={styles.price}>$89</p>
        <p style={styles.description}>{description}</p>

        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleAddToCart();
          }}
          noValidate
          aria-label="Product purchase form"
        >
          <label htmlFor="size" style={styles.label}>
            Size
          </label>
          <select
            id="size"
            value={size}
            onChange={(e) => {
              setSize(e.target.value);
              setErrors((e) => ({ ...e, size: undefined }));
              setAddedToCart(false);
            }}
            style={styles.select}
            aria-describedby={errors.size ? "size-error" : undefined}
          >
            <option value="">Select size</option>
            {[7, 8, 9, 10].map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
          {errors.size && (
            <p id="size-error" role="alert" style={styles.error}>
              {errors.size}
            </p>
          )}

          <label htmlFor="quantity" style={styles.label}>
            Quantity
          </label>
          <input
            id="quantity"
            type="number"
            min="1"
            value={quantity}
            onChange={(e) => {
              setQuantity(e.target.value);
              setErrors((e) => ({ ...e, quantity: undefined }));
              setAddedToCart(false);
            }}
            style={styles.input}
            aria-describedby={errors.quantity ? "quantity-error" : undefined}
          />
          {errors.quantity && (
            <p id="quantity-error" role="alert" style={styles.error}>
              {errors.quantity}
            </p>
          )}

          <div style={styles.buttonsRow}>
            <button
              type="submit"
              style={{ ...styles.button, marginRight: 12 }}
              aria-live="polite"
            >
              {addedToCart ? "Added to cart" : "Add to cart"}
            </button>
          </div>
        </form>
      </section>

      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
            Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
          background: #fafafa;
          color: #333;
        }
      `}</style>
    </main>
  );
}

